using UnityEngine;using System;using System.Reflection;
public static class PreviewLoadedShovel{
 public static object Run(){if(UnityEditor.EditorApplication.isPlaying)throw new Exception("Edit mode only");var old=GameObject.Find("Temporary loaded shovel preview");if(old!=null)UnityEngine.Object.DestroyImmediate(old);var source=UnityEngine.Object.FindFirstObjectByType<HeldGrainToolLevels>(FindObjectsInactive.Include);var copy=UnityEngine.Object.Instantiate(source.gameObject,source.transform.parent);copy.name="Temporary loaded shovel preview";copy.SetActive(true);var levels=copy.GetComponent<HeldGrainToolLevels>();var tool=copy.GetComponent<ShovelTool>();var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(ShovelTool).GetMethod("Awake",flags).Invoke(tool,null);int index=3;for(int i=0;i<levels.levels.Length;i++)levels.levels[i].SetActive(i==index);typeof(HeldGrainToolLevels).GetField("selected",flags).SetValue(levels,index);var pose=levels.levels[index].GetComponent<HeldShovelPose>();tool.BindShovel(pose);var physics=pose.grainPhysics;typeof(ShovelGrainPhysics).GetMethod("Awake",flags).Invoke(physics,null);tool.Cargo.Add(GrainType.Corn,tool.CapacityKg);tool.Tick(.02f);for(int i=0;i<120;i++)typeof(ShovelGrainPhysics).GetMethod("Simulate",flags).Invoke(physics,new object[]{1f/60});typeof(ShovelGrainPhysics).GetMethod("LateUpdate",flags).Invoke(physics,null);tool.ComposePresentation(1,Vector2.zero,0,Vector3.zero,out var offset,out var rotation);copy.transform.localPosition+=offset;copy.transform.localRotation*=rotation;return "Filled LVL_2 preview, kernels="+physics.KernelCount+", offset="+offset;}
}

